<script setup lang="ts">
// DemoSource is one collapsible "示例代码" block of a component page
// (components/_gen/<slug>-examples.md): the title and GitHub link render
// with the page; the highlighted Go source, generated by
// site/tools/generate-component-docs.mjs, loads when the block is opened.
import { computed, ref } from "vue";

const props = defineProps<{ demo: string; title: string; kind: string; source: string; line: number }>();

const sources = import.meta.glob<{ html: string }>("../../generated/demo-src/*.json", { import: "default" });

const html = ref("");
const state = ref<"idle" | "loading" | "failed">("idle");
const file = computed(() => props.source.split("/").pop());
const href = computed(() => `https://github.com/tangoui/tango/blob/main/${props.source}#L${props.line}`);
const what = computed(() =>
  props.kind === "func" ? "具名 Render 函数" : props.kind === "call" ? "注册调用（含 Render 函数）" : " Render 函数",
);

async function load(event: Event) {
  if (!(event.target as HTMLDetailsElement).open || html.value || state.value === "loading") return;
  const loader = sources[`../../generated/demo-src/${props.demo}.json`];
  if (!loader) {
    state.value = "failed";
    return;
  }
  state.value = "loading";
  try {
    html.value = (await loader()).html;
    state.value = "idle";
  } catch {
    state.value = "failed";
  }
}
</script>

<template>
  <details class="details custom-block demo-source" @toggle="load">
    <summary>{{ title }}</summary>
    <p>
      gallery 演示 <code>{{ demo }}</code> 的{{ what }}，源码
      <a :href="href" target="_blank" rel="noreferrer">{{ file }}#L{{ line }}</a>。
    </p>
    <div v-if="html" class="demo-source-code" v-html="html" />
    <p v-else-if="state === 'failed'" class="demo-source-note">源码加载失败，请打开上方 GitHub 链接查看。</p>
    <p v-else class="demo-source-note">加载中…</p>
  </details>
</template>

<style scoped>
.demo-source-note {
  color: var(--vp-c-text-2);
}
</style>
